        <p>Measure your foot from heel to longest toe, then find your size below.</p>
        <div className="modal-field">
          <label htmlFor="foot-length">Foot length (cm)</label>
          <input
            id="foot-length"
            type="number"
            inputMode="decimal"
            min="15"
            max="35"
            step="0.5"
            value={footLength}
            onChange={(event) => setFootLength(event.target.value)}
          />
        </div>
        <fieldset className="unit-picker">
          <legend>Unit</legend>
          <label>
            <input
              type="radio"
              name="unit"
              value="US"
              checked={unit === 'US'}
              onChange={() => setUnit('US')}
            />
            US
          </label>
          <label>
            <input
              type="radio"
              name="unit"
              value="EU"
              checked={unit === 'EU'}
