export default function ProductPage() {
  const [color, setColor] = useState('blue')
  const [selectedSize, setSelectedSize] = useState(null)
  const [quantity, setQuantity] = useState(1)
  const [cartCount, setCartCount] = useState(0)
  const [message, setMessage] = useState('')
  const [saved, setSaved] = useState(false)
  const [sizeGuideOpen, setSizeGuideOpen] = useState(false)
  const sizeGuideButtonRef = useRef(null)

  const closeSizeGuide = () => {
    setSizeGuideOpen(false)
    sizeGuideButtonRef.current?.focus()
  }

  const addToCart = () => {
    if (!selectedSize) {
      setMessage('Please pick a size before adding the Trail Runner 2 to your bag.')
      return
    }
    setCartCount((count) => count + quantity)
    setMessage(
      `Trail Runner 2 in ${COLOR_OPTIONS.find((c) => c.id === color).name}, US ${selectedSize} × ${quantity} added to your bag.`,
